using UnityEngine;
namespace Alterverse.Visuals
{
public sealed class TowerVisualShell:MonoBehaviour
{
private int team;private Transform visualRoot;public void Configure(int value){team=value;Build();}
private void Build(){if(visualRoot!=null)return;Renderer original=GetComponent<Renderer>();if(original!=null)original.enabled=false;visualRoot=new GameObject("DF_TowerVisual").transform;visualRoot.SetParent(transform,false);Color dark=team==0?StylizedArtDirection.ZeroDark:StylizedArtDirection.LumenDark;Color mid=team==0?StylizedArtDirection.ZeroMid:StylizedArtDirection.LumenMid;Color energy=team==0?StylizedArtDirection.ZeroEnergy:StylizedArtDirection.LumenEnergy;if(team==0)BuildZero(dark,mid,energy);else BuildLumen(dark,mid,energy);}
private void BuildZero(Color dark,Color mid,Color energy){Create("BrokenSpine",PrimitiveType.Cube,new Vector3(0,0,0),new Vector3(.62f,1.7f,.62f),dark,new Vector3(0,18,11));for(int i=0;i<3;i++){float a=(i*120+25)*Mathf.Deg2Rad;Create("FractureArm",PrimitiveType.Cube,new Vector3(Mathf.Cos(a)*.62f,.35f+i*.22f,Mathf.Sin(a)*.62f),new Vector3(.18f,.75f,.32f),mid,new Vector3(15+i*8,-i*37,32));}Create("RiftEye",PrimitiveType.Cube,new Vector3(0,.78f,.36f),new Vector3(.22f,.42f,.08f),energy,new Vector3(0,0,45),true);Create("SplitCrownL",PrimitiveType.Cube,new Vector3(-.32f,1.12f,0),new Vector3(.14f,.72f,.22f),mid,new Vector3(0,0,-24));Create("SplitCrownR",PrimitiveType.Cube,new Vector3(.34f,1.06f,.04f),new Vector3(.14f,.58f,.22f),energy,new Vector3(0,0,31),true);}
private void BuildLumen(Color dark,Color mid,Color energy){Create("CorePillar",PrimitiveType.Cube,new Vector3(0,0,0),new Vector3(.58f,1.65f,.58f),dark,new Vector3(0,45,0));for(int i=0;i<4;i++){float a=(45+i*90)*Mathf.Deg2Rad;Create("LightFin",PrimitiveType.Cube,new Vector3(Mathf.Cos(a)*.54f,.35f,Mathf.Sin(a)*.54f),new Vector3(.12f,1.05f,.3f),mid,new Vector3(0,-45-i*90,0));}Create("Lens",PrimitiveType.Cube,new Vector3(0,.78f,.42f),new Vector3(.3f,.3f,.08f),energy,new Vector3(0,0,45),true);Create("Crown",PrimitiveType.Cube,new Vector3(0,1.13f,0),new Vector3(.46f,.14f,.46f),energy,new Vector3(0,45,0),true);}
private GameObject Create(string name,PrimitiveType type,Vector3 pos,Vector3 scale,Color color,Vector3 rot,bool pulse=false){GameObject g=GameObject.CreatePrimitive(type);g.name="DF_"+name;g.transform.SetParent(visualRoot,false);g.transform.localPosition=pos;g.transform.localScale=scale;g.transform.localRotation=Quaternion.Euler(rot);Collider c=g.GetComponent<Collider>();if(c!=null){c.enabled=false;UnityEngine.Object.Destroy(c);}Renderer r=g.GetComponent<Renderer>();if(r!=null)r.material.color=color;if(pulse)g.AddComponent<ArenaLightPulse>();return g;}
}
}
